USE bcmr;
ALTER TABLE pedidos ADD COLUMN estoque_reservado TINYINT(1) NOT NULL DEFAULT 0;
ALTER TABLE pedidos ADD COLUMN reserva_expira_em DATETIME NULL;
CREATE TABLE IF NOT EXISTS pedido_itens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pedido_id BIGINT UNSIGNED NOT NULL,produto_id INT UNSIGNED NOT NULL,quantidade INT NOT NULL,preco_unitario DECIMAL(12,2) NOT NULL,subtotal DECIMAL(12,2) NOT NULL,FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE,FOREIGN KEY(produto_id) REFERENCES produtos(id));
CREATE TABLE IF NOT EXISTS pagamentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,empresa_id INT UNSIGNED NOT NULL,pedido_id BIGINT UNSIGNED NULL,forma ENUM('PIX','CARTAO','DINHEIRO','LINK_PAGAMENTO','OUTRO') NOT NULL DEFAULT 'PIX',gateway VARCHAR(80) NOT NULL DEFAULT 'MANUAL',valor DECIMAL(12,2) NOT NULL,status ENUM('PENDENTE','APROVADO','RECUSADO','CANCELADO','ESTORNADO') NOT NULL DEFAULT 'PENDENTE',identificador_externo VARCHAR(190) NULL,idempotency_key VARCHAR(190) NULL UNIQUE,payload_gateway JSON NULL,pago_em DATETIME NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,atualizado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_pagamentos_status(status,criado_em),FOREIGN KEY(empresa_id) REFERENCES empresas(id),FOREIGN KEY(pedido_id) REFERENCES pedidos(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS push_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,token VARCHAR(500) NOT NULL,plataforma ENUM('ANDROID','IOS','WEB') NOT NULL DEFAULT 'WEB',ativo TINYINT(1) NOT NULL DEFAULT 1,ultimo_uso DATETIME NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_push_token(token(190)),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS push_envios (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id INT UNSIGNED NOT NULL,evento_id BIGINT UNSIGNED NULL,titulo VARCHAR(255) NOT NULL,mensagem TEXT NULL,prioridade ENUM('INFORMATIVO','ATENCAO','CRITICO') NOT NULL DEFAULT 'INFORMATIVO',status ENUM('PENDENTE','ENVIANDO','ENVIADO','ERRO') NOT NULL DEFAULT 'PENDENTE',tentativa INT NOT NULL DEFAULT 0,erro TEXT NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,enviado_em DATETIME NULL,INDEX idx_push_status(status,criado_em),FOREIGN KEY(usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,FOREIGN KEY(evento_id) REFERENCES eventos(id) ON DELETE SET NULL);
ALTER TABLE documentos ADD COLUMN mime_type VARCHAR(150) NULL;
ALTER TABLE documentos ADD COLUMN tamanho_bytes BIGINT UNSIGNED NULL;
ALTER TABLE documentos ADD COLUMN sha256 CHAR(64) NULL;
ALTER TABLE documentos ADD COLUMN extraido_json JSON NULL;
ALTER TABLE documentos ADD COLUMN status_processamento ENUM('NAO_SOLICITADO','PENDENTE','PROCESSANDO','CONCLUIDO','ERRO') NOT NULL DEFAULT 'NAO_SOLICITADO';
CREATE TABLE IF NOT EXISTS documento_processamentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,documento_id BIGINT UNSIGNED NOT NULL,tipo_processamento ENUM('EXTRACAO_LOCAL','IA') NOT NULL DEFAULT 'IA',status ENUM('PENDENTE','PROCESSANDO','CONCLUIDO','ERRO') NOT NULL DEFAULT 'PENDENTE',tentativa INT NOT NULL DEFAULT 0,resultado_json JSON NULL,erro TEXT NULL,criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,processado_em DATETIME NULL,INDEX idx_docproc_status(status,criado_em),FOREIGN KEY(documento_id) REFERENCES documentos(id) ON DELETE CASCADE);
INSERT IGNORE INTO pagamentos(empresa_id,pedido_id,forma,gateway,valor,status,identificador_externo,pago_em) SELECT 1,id,'PIX','DEMO',total,'APROVADO',CONCAT('DEMO-',codigo),criado_em FROM pedidos WHERE status='PAGO';
